				word := currentWord.String()
				wordCount[word]++
				currentWord.Reset()
			}
		}
	}

	// Don't forget the last word
	if currentWord.Len() > 0 {
		word := currentWord.String()
		wordCount[word]++
	}

	// Convert to slice for sorting
	type wordFreq struct {
