			LastName:  lastName,
			Birthday:  birthday,
			Age:       age,
			Relatives: relatives,
		})
	}

	encoder := json.NewEncoder(os.Stdout)
	encoder.SetIndent("", "  ")
	encoder.Encode(people)
}
