        fmt.Fprintf(os.Stderr, "Error reading CSV: %v\n", err)
        os.Exit(1)
    }

    if len(records) < 2 {
        fmt.Fprintf(os.Stderr, "CSV file has no data rows\n")
        os.Exit(1)
    }

    var people []Person
    for i, record := range records {
        if i == 0 {
            continue // Skip header
        }

        if len(record) < 4 {
            fmt.Fprintf(os.Stderr, "Row %d has insufficient fields\n", i)
            os.Exit(1)
        }

        age, err := strconv.Atoi(record[1])
        if err != nil {
            fmt.Fprintf(os.Stderr, "Error parsing age for row %d: %v\n", i, err)
            os.Exit(1)
        }

        score, err := strconv.ParseFloat(record[3], 64)
        if err != nil {
            fmt.Fprintf(os.Stderr, "Error parsing score for row %d: %v\n", i, err)
            os.Exit(1)
        }

        person := Person{
            Name:  record[0],
            Age:   age,
            Email: record[2],
            Score: score,
        }
        people = append(people, person)
    }

    data, err := json.MarshalIndent(people, "", "  ")
    if err != nil {
        fmt.Fprintf(os.Stderr, "Error marshaling JSON: %v\n", err)
        os.Exit(1)
    }

    fmt.Print(string(data))
}
